{
  "givens": [
    {
      "name": "function_definition",
      "quote": "Determine the domain such that the function f(x)=sqrt(x−2)+x(e)^(x) is continuous over its domain."
    }
  ],
  "requirements": [
    {
      "name": "domain_of_square_root",
      "necessity": "The domain of sqrt(u) is the set of u such that u ≥ 0. Here u = x−2, so we need x−2 ≥ 0 → x ≥ 2.",
      "search_query": "domain of sqrt function"
    },
    {
      "name": "domain_of_exponential",
      "necessity": "The exponential function e^x is defined for all real x, so it imposes no restriction on the domain.",
      "search_query": "domain of e^x"
    },
    {
      "name": "continuity_of_sum",
      "necessity": "The sum of two continuous functions is continuous on the intersection of their domains. Thus, once the domain is determined, continuity follows automatically.",
      "search_query": "continuity of sum of functions"
    },
    {
      "name": "continuity_of_product",
      "necessity": "The product of two continuous functions is continuous. The term x·e^x is a product of continuous functions on ℝ, so it is continuous everywhere.",
      "search_query": "continuity of product of functions"
    },
    {
      "name": "continuity_of_exponential",
      "necessity": "The exponential function e^x is continuous for all real x.",
      "search_query": "continuity of e^x"
    },
    {
      "name": "continuity_of_square_root",
      "necessity": "The square root function sqrt(u) is continuous for u ≥ 0.",
      "search_query": "continuity of sqrt function"
    }
  ]
}

